#!/usr/bin/env bash\nset -e\n\n# Build the Docker image\nIMAGE_NAME=nightly-quote-mixer-test\ndocker build -t $IMAGE_NAME .\n\n# Run the container in detached mode\nCONTAINER_ID=$(docker run -d -p 5001:5000 $IMAGE_NAME)\n\n# Ensure container is stopped on exit\ncleanup() {\n  echo "Stopping container $CONTAINER_ID"\n  docker rm -f $CONTAINER_ID > /dev/null 2>&1 || true\n}\ntrap cleanup EXIT\n\n# Wait for the service to become reachable (max 5 seconds)\nfor i in {1..5}; do\n  if curl -s http://localhost:5001/quote?seed=0 > /dev/null; then\n    break\n  fi\n  sleep 1\ndone\n\n# Query the service with a known seed\nRESPONSE=$(curl -s http://localhost:5001/quote?seed=2)\nEXPECTED='{"quote":"Stars are just night-time fireflies that got lost."}'\n\n# Simple assertion\nif [ "$RESPONSE" != "$EXPECTED" ]; then\n  echo "Test failed: expected $EXPECTED but got $RESPONSE"\n  exit 1\nfi\n\necho "Test passed: received expected quote."\n
